// tests/constants.test.js
const { STATUSES, STATUS_BY_MARKER, STATUS_BY_KEY, SUBTASK_STATUS_CYCLE, TASK_LINE_RE, BLOCK_ID_RE } = require("../js/constants");

describe("STATUS_BY_MARKER", () => {
  test("known markers resolve correctly", () => {
    expect(STATUS_BY_MARKER.get(" ").key).toBe("open");
    expect(STATUS_BY_MARKER.get("").key).toBe("open");
    expect(STATUS_BY_MARKER.get("x").key).toBe("done");
    expect(STATUS_BY_MARKER.get("X").key).toBe("done");
    expect(STATUS_BY_MARKER.get("/").key).toBe("progress");
    expect(STATUS_BY_MARKER.get("-").key).toBe("canceled");
    expect(STATUS_BY_MARKER.get("?").key).toBe("proposal");
  });

  test("unknown marker returns undefined (caller falls back to STATUSES[0])", () => {
    expect(STATUS_BY_MARKER.get("!")).toBeUndefined();
  });
});

describe("TASK_LINE_RE", () => {
  test.each([
    ["- [ ] simple task", " ", "simple task"],
    ["  - [x] indented", "x", "indented"],
    ["\t- [/] tabbed", "/", "tabbed"],
    ["- [-] canceled task ^abc", "-", "canceled task ^abc"],
  ])("parses %s", (line, marker, text) => {
    const m = line.match(TASK_LINE_RE);
    expect(m).not.toBeNull();
    expect(m[2]).toBe(marker);
    expect(m[3].trim()).toBe(text);
  });

  test("non-task line returns null", () => {
    expect("# heading".match(TASK_LINE_RE)).toBeNull();
    expect("plain text".match(TASK_LINE_RE)).toBeNull();
    expect("- no brackets".match(TASK_LINE_RE)).toBeNull();
  });
});

describe("SUBTASK_STATUS_CYCLE", () => {
  test("contains open, progress, done in order", () => {
    expect(SUBTASK_STATUS_CYCLE.map(s => s.key)).toEqual(["open", "progress", "done"]);
  });
});
