// tests/block-ids.test.js
const blockIds = require("../js/plugin/block-ids");

// block-ids uses `this` — bind a minimal context
const ctx = Object.assign(Object.create(null), blockIds);

describe("hashString", () => {
  test("deterministic", () => {
    expect(ctx.hashString("hello")).toBe(ctx.hashString("hello"));
  });

  test("different inputs produce different hashes", () => {
    expect(ctx.hashString("a")).not.toBe(ctx.hashString("b"));
  });

  test("empty string does not throw", () => {
    expect(() => ctx.hashString("")).not.toThrow();
  });

  test("unicode input", () => {
    expect(() => ctx.hashString("🔥задача")).not.toThrow();
  });
});

describe("createUniqueBlockId", () => {
  const file = { path: "notes/test.md" };

  test("returns base id when no collision", () => {
    const id = ctx.createUniqueBlockId(file, 0, "task text", new Set());
    expect(id).toMatch(/^tk-[a-z0-9]+$/);
  });

  test("appends suffix on collision", () => {
    const usedIds = new Set();
    const first = ctx.createUniqueBlockId(file, 0, "task text", usedIds);
    usedIds.add(first);
    const second = ctx.createUniqueBlockId(file, 0, "task text", usedIds);
    expect(second).toBe(`${first}-2`);
    usedIds.add(second);
    const third = ctx.createUniqueBlockId(file, 0, "task text", usedIds);
    expect(third).toBe(`${first}-3`);
  });
});

describe("ensureTaskBlockIds", () => {
  const file = { path: "notes/test.md" };

  test("adds block id to task without one", () => {
    const content = "- [ ] do something\n";
    const result = ctx.ensureTaskBlockIds(file, content);
    expect(result).toMatch(/\^tk-[a-z0-9]+/);
  });

  test("does not re-add id to task that already has one", () => {
    const content = "- [ ] do something ^existing-id\n";
    const result = ctx.ensureTaskBlockIds(file, content);
    const matches = result.match(/\^/g);
    expect(matches).toHaveLength(1); // only original caret
  });

  test("skips tasks inside kanban block", () => {
    const content = `<!-- task-kanban:start -->\n- [ ] inside kanban\n<!-- task-kanban:end -->\n`;
    const result = ctx.ensureTaskBlockIds(file, content);
    expect(result).not.toMatch(/\^tk-/);
  });

  test("handles CRLF line endings", () => {
    const content = "- [ ] task one\r\n- [ ] task two\r\n";
    expect(() => ctx.ensureTaskBlockIds(file, content)).not.toThrow();
  });
});

describe("findTopInsertIndex", () => {
  test("no frontmatter → 0", () => {
    expect(ctx.findTopInsertIndex(["# Title", "content"])).toBe(0);
  });

  test("frontmatter → after closing ---", () => {
    const lines = ["---", "title: test", "---", "", "# Content"];
    expect(ctx.findTopInsertIndex(lines)).toBe(4); // after blank line
  });

  test("unclosed frontmatter → 0", () => {
    const lines = ["---", "title: test", "# No closing"];
    expect(ctx.findTopInsertIndex(lines)).toBe(0);
  });
});

describe("replaceOrInsertKanbanBlock", () => {
  test("replaces existing kanban block", () => {
    const content = "# Title\n\n<!-- task-kanban:start -->\nold content\n<!-- task-kanban:end -->\n\nTrailing\n";
    const result = ctx.replaceOrInsertKanbanBlock(content, "<!-- task-kanban:start -->\nnew\n<!-- task-kanban:end -->");
    expect(result).toContain("new");
    expect(result).not.toContain("old content");
    expect(result).toContain("Trailing");
  });

  test("inserts block when none exists", () => {
    const content = "# Title\n\nSome text\n";
    const result = ctx.replaceOrInsertKanbanBlock(content, "<!-- task-kanban:start -->\nnew\n<!-- task-kanban:end -->");
    expect(result).toContain("new");
    expect(result).toContain("Some text");
  });
});

describe("removeKanbanBlock", () => {
  test("removes kanban block", () => {
    const content = "Before\n\n<!-- task-kanban:start -->\nblock\n<!-- task-kanban:end -->\n\nAfter\n";
    const result = ctx.removeKanbanBlock(content);
    expect(result).not.toContain("block");
    expect(result).toContain("Before");
    expect(result).toContain("After");
  });

  test("returns unchanged content when no kanban block", () => {
    const content = "No kanban here\n";
    expect(ctx.removeKanbanBlock(content)).toBe(content);
  });

  test("handles end marker before start marker (malformed)", () => {
    const content = "<!-- task-kanban:end -->\n<!-- task-kanban:start -->\n";
    const result = ctx.removeKanbanBlock(content);
    expect(result).toBe(content); // endIndex <= startIndex → unchanged
  });
});
