// tests/tasks.test.js
const tasks = require("../js/plugin/tasks");
const { STATUSES } = require("../js/constants");
const ctx = Object.assign(Object.create(null), tasks);
const mockFile = { path: "notes/test.md" };

describe("getIndentLevel", () => {
  test("empty string → 0", () => expect(ctx.getIndentLevel("")).toBe(0));
  test("4 spaces → 4", () => expect(ctx.getIndentLevel("    ")).toBe(4));
  test("1 tab → 4", () => expect(ctx.getIndentLevel("\t")).toBe(4));
  test("2 tabs → 8", () => expect(ctx.getIndentLevel("\t\t")).toBe(8));
  test("tab + 2 spaces → 6", () => expect(ctx.getIndentLevel("\t  ")).toBe(6));
});

describe("scanTasksInContent", () => {
  test("parses basic task", () => {
    const content = "- [ ] simple task\n";
    const roots = ctx.scanTasksInContent(mockFile, content);
    expect(roots).toHaveLength(1);
    expect(roots[0].text).toBe("simple task");
    expect(roots[0].status.key).toBe("open");
  });

  test("parses priority emoji", () => {
    const content = "- [ ] 🔥🔥 high priority\n";
    const roots = ctx.scanTasksInContent(mockFile, content);
    expect(roots[0].priority).toBe(2);
  });

  test("skips content inside kanban block", () => {
    const content = `- [ ] before\n<!-- task-kanban:start -->\n- [ ] inside\n<!-- task-kanban:end -->\n- [ ] after\n`;
    const roots = ctx.scanTasksInContent(mockFile, content);
    expect(roots).toHaveLength(2);
    expect(roots.map(r => r.text)).toEqual(["before", "after"]);
  });

  test("nests subtasks correctly", () => {
    const content = "- [ ] parent\n  - [x] child\n";
    const roots = ctx.scanTasksInContent(mockFile, content);
    expect(roots).toHaveLength(1);
    expect(roots[0].subtasks).toHaveLength(1);
    expect(roots[0].subtasks[0].status.key).toBe("done");
  });

  test("extracts blockId", () => {
    const content = "- [ ] task with id ^tk-abc123\n";
    const roots = ctx.scanTasksInContent(mockFile, content);
    expect(roots[0].blockId).toBe("tk-abc123");
    expect(roots[0].text).toBe("task with id");
  });

  test("tracks heading", () => {
    const content = "## My Section\n- [ ] task under heading\n";
    const roots = ctx.scanTasksInContent(mockFile, content);
    expect(roots[0].heading).toBe("My Section");
  });

  test("handles CRLF line endings", () => {
    const content = "- [ ] task one\r\n- [x] task two\r\n";
    const roots = ctx.scanTasksInContent(mockFile, content);
    expect(roots).toHaveLength(2);
  });

  test("unknown marker falls back to open status", () => {
    const content = "- [!] unknown marker task\n";
    const roots = ctx.scanTasksInContent(mockFile, content);
    expect(roots[0].status).toBe(STATUSES[0]);
  });

  test("empty content returns empty array", () => {
    expect(ctx.scanTasksInContent(mockFile, "")).toHaveLength(0);
    expect(ctx.scanTasksInContent(mockFile, "# just a heading\n")).toHaveLength(0);
  });
});
