// tests/state.test.js
const state = require("../js/plugin/state");
const { STATUSES, SUBTASK_STATUS_CYCLE } = require("../js/constants");

function makeCtx(overrides = {}) {
  return Object.assign(Object.create(null), state, {
    taskKanbanSortMode: "default",
    taskKanbanTouchedAt: {},
    ...overrides,
  });
}

describe("getNextStatus", () => {
  test("cycles through all statuses", () => {
    const ctx = makeCtx();
    let status = STATUSES[0];
    for (let i = 1; i < STATUSES.length; i++) {
      status = ctx.getNextStatus(status);
      expect(status).toBe(STATUSES[i]);
    }
    // wraps
    expect(ctx.getNextStatus(STATUSES[STATUSES.length - 1])).toBe(STATUSES[0]);
  });
});

describe("getNextSubtaskStatus", () => {
  test("cycles open → progress → done → open", () => {
    const ctx = makeCtx();
    expect(ctx.getNextSubtaskStatus(SUBTASK_STATUS_CYCLE[0]).key).toBe("progress");
    expect(ctx.getNextSubtaskStatus(SUBTASK_STATUS_CYCLE[1]).key).toBe("done");
    expect(ctx.getNextSubtaskStatus(SUBTASK_STATUS_CYCLE[2]).key).toBe("open");
  });

  test("status not in cycle → returns cycle[0]", () => {
    const ctx = makeCtx();
    const canceled = STATUSES.find(s => s.key === "canceled");
    expect(ctx.getNextSubtaskStatus(canceled)).toBe(SUBTASK_STATUS_CYCLE[0]);
  });
});

describe("getTaskTouchedKey", () => {
  const ctx = makeCtx();
  ctx.hashString = (v) => "HASH"; // stub

  test("null task → empty string", () => {
    expect(ctx.getTaskTouchedKey(null)).toBe("");
  });

  test("task with no file.path → empty string", () => {
    expect(ctx.getTaskTouchedKey({ file: {} })).toBe("");
  });

  test("task with blockId uses path#blockId", () => {
    const key = ctx.getTaskTouchedKey({ file: { path: "a.md" }, blockId: "abc", line: 0, raw: "" });
    expect(key).toBe("a.md#abc");
  });

  test("task without blockId uses path:line:hash", () => {
    const key = ctx.getTaskTouchedKey({ file: { path: "a.md" }, blockId: "", line: 3, raw: "text" });
    expect(key).toBe("a.md:3:HASH");
  });
});

describe("sortTasksForKanban", () => {
  function task(statusIndex, priority, path, line, touchedKey) {
    return { status: STATUSES[statusIndex], priority, file: { path }, line };
  }

  test("default mode: sorts by status then file path then line", () => {
    const ctx = makeCtx({ taskKanbanSortMode: "default" });
    ctx.getTaskTouchedKey = () => "";
    const t1 = task(1, 0, "b.md", 0);
    const t2 = task(0, 0, "a.md", 5);
    const t3 = task(0, 0, "a.md", 2);
    const sorted = ctx.sortTasksForKanban([t1, t2, t3]);
    expect(sorted).toEqual([t3, t2, t1]);
  });

  test("priority mode: higher priority sorts first within same status", () => {
    const ctx = makeCtx({ taskKanbanSortMode: "priority" });
    ctx.getTaskTouchedKey = () => "";
    const low = task(0, 1, "a.md", 0);
    const high = task(0, 3, "a.md", 1);
    const sorted = ctx.sortTasksForKanban([low, high]);
    expect(sorted[0]).toBe(high);
  });

  test("touched mode: recently touched sorts first", () => {
    const t1 = task(0, 0, "a.md", 0);
    const t2 = task(0, 0, "a.md", 1);
    const ctx = makeCtx({
      taskKanbanSortMode: "touched",
      taskKanbanTouchedAt: { "key-t1": 2000, "key-t2": 1000 },
    });
    ctx.getTaskTouchedKey = (t) => t === t1 ? "key-t1" : "key-t2";
    const sorted = ctx.sortTasksForKanban([t2, t1]);
    expect(sorted[0]).toBe(t1);
  });
});

describe("getInlineLine", () => {
  const ctx = makeCtx();

  test("null element → null", () => expect(ctx.getInlineLine(null)).toBeNull());
  test("missing attr → null", () => {
    const el = { getAttribute: () => null };
    expect(ctx.getInlineLine(el)).toBeNull();
  });
  test("empty attr → null", () => {
    const el = { getAttribute: () => "" };
    expect(ctx.getInlineLine(el)).toBeNull();
  });
  test("valid int string → number", () => {
    const el = { getAttribute: () => "42" };
    expect(ctx.getInlineLine(el)).toBe(42);
  });
  test("non-numeric string → null", () => {
    const el = { getAttribute: () => "abc" };
    expect(ctx.getInlineLine(el)).toBeNull();
  });
